import { expect } from '@playwright/test';
import type { Page } from '@playwright/test';
import { createGame } from '../../src/game/create-game.ts';

export const SAMPLE_CODE = 'np1-4-1';
export const SAMPLE_DECK = [6, 7, 0, 5, 2, 2, 0, 5, 3, 7, 1, 6, 4, 4, 1, 3];
export const cards = (page: Page) => page.getByRole('region', { name: 'Card board' }).getByRole('button');

export async function showReproduction(page: Page): Promise<void> {
  if (await page.locator('details').getAttribute('open') === null) {
    await page.getByText('Reproduce a game', { exact: true }).click();
  }
}

export async function loadBoard(page: Page, code = SAMPLE_CODE): Promise<void> {
  await showReproduction(page);
  await page.getByLabel('Board code', { exact: true }).fill(code);
  await page.getByRole('button', { name: 'Load board', exact: true }).click();
}

export async function openGame(page: Page, code = SAMPLE_CODE): Promise<void> {
  await page.goto('/');
  await loadBoard(page, code);
}

export function dealPairs(code = SAMPLE_CODE): readonly (readonly [number, number])[] {
  const game = createGame(code);
  if (game === null) throw new Error('Invalid test deal');
  const pairs: [number, number][] = [];
  for (let face = 0; face < game.deck.length / 2; face += 1) {
    const positions = game.deck.flatMap((value, index) => value === face ? [index] : []);
    const first = positions[0];
    const second = positions[1];
    if (first === undefined || second === undefined) throw new Error('Incomplete test deal');
    pairs.push([first, second]);
  }
  return pairs;
}

export async function finishDeal(page: Page, code = SAMPLE_CODE): Promise<void> {
  for (const pair of dealPairs(code)) {
    for (const index of pair) await cards(page).nth(index).click();
  }
  await expect(page.getByRole('region', { name: 'Game complete' })).toBeVisible();
}

export async function freezeClock(page: Page): Promise<void> {
  await page.clock.install({ time: new Date('2026-11-04T12:00:00Z') });
  await page.clock.pauseAt(new Date('2026-11-04T12:00:01Z'));
}
import { expect, test } from '@playwright/test';
import { SUPPORTED_SIZES } from '../../src/game/board-code.ts';
import { cards, finishDeal, freezeClock, openGame } from './deal-actions.ts';

for (const size of SUPPORTED_SIZES) {
  test(`finishes every pair of ${size}x${size}`, async ({ page }) => {
    const code = `np1-${size}-1`;
    await openGame(page, code);
    await expect(cards(page)).toHaveCount(size * size);
    await finishDeal(page, code);
    await expect(page.getByText(`Moves: ${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(page.getByText(`Pairs: ${size * size / 2}/${size * size / 2}`, { exact: true })).toBeVisible();
    await expect(cards(page).locator('[aria-hidden="true"]').first()).toBeAttached();
    await expect(page.locator('.card[aria-disabled="true"]')).toHaveCount(size * size);
  });
}

test('reveals once, matches immediately, ignores matched input, and times a miss exactly', async ({ page }) => {
  await freezeClock(page);
  await openGame(page);
  await page.clock.runFor(2000);
  await expect(page.getByText('Time: 0:00', { exact: true })).toBeVisible();
  await cards(page).nth(0).click();
  await cards(page).nth(0).click();
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await cards(page).nth(11).click();
  await expect(page.getByText('Pairs: 1/8', { exact: true })).toBeVisible();
  await cards(page).nth(0).click({ force: true });
  await expect(page.getByText('Moves: 1', { exact: true })).toBeVisible();
  await cards(page).nth(1).click();
  await cards(page).nth(2).click();
  await cards(page).nth(3).click();
  await expect(page.getByText('Moves: 2', { exact: true })).toBeVisible();
  await expect(page.locator('.card--revealed')).toHaveCount(4);
  await page.clock.runFor(799);
  await expect(cards(page).nth(1)).toHaveAccessibleName(/revealed$/);
  await page.clock.runFor(1);
  await expect(cards(page).nth(1)).toHaveAccessibleName('Row 1, column 2, closed');
  await expect(page.locator('.card--revealed')).toHaveCount(2);
  await page.clock.runFor(200);
  await expect(page.getByText('Time: 0:01', { exact: true })).toBeVisible();
});

test('hover, context menu and cancelled pointer do not reveal a card', async ({ page }) => {
  await openGame(page);
  const first = cards(page).first();
  await first.hover();
  await first.click({ button: 'right' });
  await page.keyboard.press('Escape');
  await first.dispatchEvent('pointercancel', { pointerType: 'touch' });
  await expect(first).toHaveAccessibleName('Row 1, column 1, closed');
  await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
  await expect(page.locator('audio, video, canvas')).toHaveCount(0);
});
import { expect, test } from '@playwright/test';
import { cards, freezeClock, loadBoard, openGame } from './deal-actions.ts';

test('hiding pauses the same elapsed and mismatch time, showing resumes only the remainder', async ({ page }) => {
  await freezeClock(page);
  await openGame(page);
  await cards(page).nth(0).click();
  await cards(page).nth(1).click();
  await page.clock.runFor(200);
  await page.evaluate(() => {
    Object.defineProperty(document, 'visibilityState', { configurable: true, value: 'hidden' });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(5000);
  await expect(page.locator('.card--revealed')).toHaveCount(2);
  await page.getByRole('button', { name: 'Export snapshot' }).click();
  await expect(page.getByLabel('Snapshot JSON')).toHaveValue(/"elapsedMs": 200/);
  await expect(page.getByLabel('Snapshot JSON')).toHaveValue(/"remainingMs": 600/);
  await page.evaluate(() => {
    Object.defineProperty(document, 'visibilityState', { configurable: true, value: 'visible' });
    document.dispatchEvent(new Event('visibilitychange'));
  });
  await page.clock.runFor(599);
  await expect(page.locator('.card--revealed')).toHaveCount(2);
  await page.clock.runFor(1);
  await expect(page.locator('.card--revealed')).toHaveCount(0);
  await page.getByRole('button', { name: 'Export snapshot' }).click();
  await expect(page.getByLabel('Snapshot JSON')).toHaveValue(/"elapsedMs": 800/);
});

for (const action of ['Restart', 'New Game', 'Load board'] as const) {
  test(`${action} during a mismatch invalidates the earlier timer`, async ({ page }) => {
    await freezeClock(page);
    await openGame(page);
    await cards(page).nth(0).click();
    await cards(page).nth(1).click();
    await page.clock.runFor(300);
    if (action === 'Load board') await loadBoard(page);
    else await page.getByRole('button', { name: action, exact: true }).click();
    await expect(page.getByRole('button', { name: action, exact: true })).toBeFocused();
    await expect(page.getByText('Moves: 0', { exact: true })).toBeVisible();
    await cards(page).nth(2).click();
    await page.clock.runFor(1000);
    await expect(cards(page).nth(2)).toHaveAccessibleName(/revealed$/);
    await expect(page.locator('.card--revealed')).toHaveCount(1);
    await expect(cards(page).first()).toHaveAttribute('tabindex', '-1');
  });
}

