import assert from 'node:assert/strict';
import { createHash } from 'node:crypto';
import { readFile, readdir, writeFile } from 'node:fs/promises';
const files = [];
for (const root of ['src', 'scripts', 'tests']) {
  for (const name of await readdir(root, { recursive: true })) {
    if (/\.tsx?$/.test(name)) files.push(`${root}/${name}`);
  }
}
for (const name of await readdir('.')) if (/\.config\.ts$/.test(name)) files.push(name);
const counts = await Promise.all(files.map(async path => ({ path, lines: (await readFile(path, 'utf8')).trimEnd().split('\n').length })));
const maximum = Math.max(...counts.map(file => file.lines));
assert.ok(maximum <= 200);
const html = await readFile('dist/index.html');
assert.equal(html.length, 240575);
